// 1. جلب الملف بمرونة
const binaryData = $input.first().binary || {};
const resumeBinary = binaryData.Resume__PDF_only_ || binaryData.Resume || Object.values(binaryData)[0];

if (!resumeBinary) {
  throw new Error('لم يتم العثور على أي ملف مرفوع. يرجى رفع السيرة الذاتية.');
}

const fileName = resumeBinary.fileName || 'unknown';
const mimeType = (resumeBinary.mimeType || '').toLowerCase();
const fileExt = (resumeBinary.fileExtension || fileName.split('.').pop() || '').toLowerCase();

// 2. التحقق من نوع الملف والامتداد (دون تعقيدات Base64 غير المتوافقة مع n8n)
const isPdf = mimeType.includes('pdf') || fileExt === 'pdf';

if (!isPdf) {
  throw new Error(`الملف المرفوع "${fileName}" ليس بصيغة PDF صالحة (mimeType=${mimeType}).`);
}

// 3. حساب الحجم بدقة والتحقق من الحد الأقصى (5MB)
let sizeBytes = 0;
if (typeof resumeBinary.fileSize === 'number') {
  sizeBytes = resumeBinary.fileSize;
} else if (typeof resumeBinary.fileSize === 'string') {
  const sizeStr = resumeBinary.fileSize.toLowerCase();
  const num = parseFloat(sizeStr);
  if (sizeStr.includes('mb')) sizeBytes = num * 1024 * 1024;
  else if (sizeStr.includes('kb')) sizeBytes = num * 1024;
  else if (sizeStr.includes('gb')) sizeBytes = num * 1024 * 1024 * 1024;
  else sizeBytes = num;
} else if (resumeBinary.data) {
  sizeBytes = Math.round((resumeBinary.data.length * 3) / 4);
}

if (sizeBytes > 5 * 1024 * 1024) {
  throw new Error(`حجم الملف كبير جداً (${(sizeBytes / 1024 / 1024).toFixed(2)} MB). الحد الأقصى 5MB.`);
}

// 4. تمرير البيانات مع توحيد اسم الملف إلى Resume ليعمل مباشرة مع نود Extract PDF Text
return {
  json: {
    ...$input.first().json,
    fileName,
    fileSizeKB: Math.round(sizeBytes / 1024),
    isValidPdf: true,
  },
  binary: {
    ...binaryData,
    Resume: resumeBinary
  }
};

// Improvement: Clean CV text before sending to AI - reduces tokens, improves matching
const formData = $('On form submission').first().json;
const rawText = $input.first().json.text || '';

// Clean up: normalize whitespace, remove repeated blank lines, trim
const cleaned = rawText
  .replace(/\r\n/g, '\n')
  .replace(/\r/g, '\n')
  .replace(/[ \t]+/g, ' ')
  .replace(/\n{3,}/g, '\n\n')
  .replace(/^\s+|\s+$/gm, '')
  .trim();

// Truncate to ~12K chars (~3K tokens) - keeps under free model context window
const maxChars = 12000;
const truncated = cleaned.length > maxChars
  ? cleaned.substring(0, maxChars) + '\n[...CV truncated...]'
  : cleaned;

return {
  json: {
    applicantName: formData['Full Name'],
    applicantEmail: formData['Email Address'],
    applicantPhone: formData['Phone Number'],
    appliedPosition: formData['Position Applied For'],
    yearsExperienceClaimed: formData['Years of Experience'],
    resumeText: truncated,
    resumeCharCount: cleaned.length,
    wasTruncated: cleaned.length > maxChars,
  }
};

// 1. Extract candidate data and safely validate input
const item = $input.first();
const cv = (item && item.json) ? item.json : {};

// Normalize applied position (trim whitespace and match case-insensitively)
const rawPosition = (cv.appliedPosition || '').toString().trim();

// 2. Job Descriptions & Evaluation Weights Database
const jdDatabase = {
  "Frontend Engineer": {
    "required_skills": [
      { "skill": "React", "weight": 10 },
      { "skill": "TypeScript", "weight": 8 },
      { "skill": "JavaScript (ES6+)", "weight": 8 },
      { "skill": "HTML5", "weight": 5 },
      { "skill": "CSS3", "weight": 5 },
      { "skill": "Responsive Design", "weight": 6 },
      { "skill": "REST APIs", "weight": 6 },
      { "skill": "Git", "weight": 5 }
    ],
    "nice_to_have": [
      { "skill": "Redux", "weight": 7 },
      { "skill": "Next.js", "weight": 7 },
      { "skill": "Webpack/Vite", "weight": 5 },
      { "skill": "Jest/Testing", "weight": 5 },
      { "skill": "GraphQL", "weight": 4 },
      { "skill": "CI/CD", "weight": 4 }
    ],
    "min_experience_years": 3,
    "education": "Bachelor's degree in Computer Science, Software Engineering, or related technical field"
  },
  "Data Analyst": {
    "required_skills": [
      { "skill": "SQL", "weight": 10 },
      { "skill": "Python", "weight": 8 },
      { "skill": "Pandas", "weight": 7 },
      { "skill": "Power BI or Tableau", "weight": 8 },
      { "skill": "Statistics", "weight": 6 },
      { "skill": "Data Visualization", "weight": 6 },
      { "skill": "Excel", "weight": 5 },
      { "skill": "Data Modeling", "weight": 7 }
    ],
    "nice_to_have": [
      { "skill": "R", "weight": 4 },
      { "skill": "Snowflake", "weight": 4 },
      { "skill": "Airflow", "weight": 4 },
      { "skill": "dbt", "weight": 4 },
      { "skill": "Machine Learning basics", "weight": 5 },
      { "skill": "A/B Testing", "weight": 5 }
    ],
    "min_experience_years": 2,
    "education": "Degree in Computer Science, Data Science, Statistics, Business Analytics, or related quantitative field"
  },
  "Product Manager": {
    "required_skills": [
      { "skill": "Product Strategy", "weight": 8 },
      { "skill": "User Journey Mapping", "weight": 7 },
      { "skill": "Backlog Prioritization", "weight": 7 },
      { "skill": "Stakeholder Management", "weight": 7 },
      { "skill": "Roadmap Planning", "weight": 6 },
      { "skill": "User Stories", "weight": 6 },
      { "skill": "Agile/Scrum", "weight": 6 },
      { "skill": "Analytics", "weight": 5 }
    ],
    "nice_to_have": [
      { "skill": "SQL", "weight": 4 },
      { "skill": "Wireframing (Figma)", "weight": 5 },
      { "skill": "A/B Testing", "weight": 5 },
      { "skill": "Market Research", "weight": 5 },
      { "skill": "KPI Definition", "weight": 6 },
      { "skill": "Jira", "weight": 4 }
    ],
    "min_experience_years": 3,
    "education": "Degree in Business, Computer Science, Engineering, or relevant practical experience"
  }
};

// Match applied position with fallback to Data Analyst
const matchedPosition = Object.keys(jdDatabase).find(
  key => key.toLowerCase() === rawPosition.toLowerCase()
) || "Data Analyst";

const jd = jdDatabase[matchedPosition];

const requiredSkillsList = jd.required_skills.map(s => s.skill).join(', ');
const niceToHaveList = jd.nice_to_have.map(s => s.skill).join(', ');

// 3. Strict AI system prompt preventing markdown wrappers and hallucinations
const systemPrompt = `You are a strict, objective Technical HR Evaluator.
Evaluate the candidate's resume against the Job Description.
Output Rules:
1. Return ONLY a single raw JSON object. Never use markdown code fences (do NOT include \`\`\` or \`\`\`json).
2. Do not invent details not explicitly mentioned in the CV.
3. Accept common synonyms for tools/technologies (e.g., PostgreSQL counts as SQL, Pandas counts as Pandas).
4. "experience_years_actual" must be a pure number (integer or float), never text.
5. In "fit_summary", generate an all-in-one comprehensive narrative summary covering the candidate's entire background: previous companies/roles, practical hands-on projects, formal trainings/certifications, and final role suitability.`;

// 4. Prompt schema focusing everything into fit_summary
const userPrompt = `Job Specification:
- Position: ${matchedPosition}
- Minimum Required Experience: ${jd.min_experience_years} years
- Required Skills: ${requiredSkillsList}
- Nice-to-Have Skills: ${niceToHaveList}
- Required Education: ${jd.education}

Candidate Resume:
${cv.resumeText || ''}

Evaluate the candidate and return the output matching this EXACT JSON schema:
{
  "extracted_skills": ["list of all technical tools, languages, and skills found in CV"],
  "skills_matched": ["subset of Required Skills found in candidate CV"],
  "missing_skills": ["subset of Required Skills completely missing from CV"],
  "nice_to_have_matched": ["subset of Nice-to-Have Skills found in CV"],
  "experience_years_actual": 0,
  "education_detected": "Degree, major, and institution detected from CV, or empty string",
  "education_match": true,
  "fit_summary": "Comprehensive 1-paragraph executive summary covering the whole CV: Start with experience level and past companies worked for, highlight notable real-world projects and key technical achievements, mention completed courses/certifications, and conclude with an objective verdict on why this candidate matches the role."
}`;

return {
  json: {
    ...cv,
    position: matchedPosition,
    jdObject: jd,
    aiSystemPrompt: systemPrompt,
    aiUserPrompt: userPrompt
  }
};

// 1. Retrieve job details and candidate context directly from the preparation node
const prev = $('Prepare JD & Stage 1 Prompt').first().json;
const jd = prev.jdObject;

// 2. Read and sanitize AI completion response
const inputData = $input.first().json;
const rawContent = (inputData.choices && inputData.choices[0] && inputData.choices[0].message) 
  ? inputData.choices[0].message.content 
  : '';

// Strip markdown formatting, code blocks, and reasoning tags if present
const cleanJson = rawContent
  .replace(/<think>[\s\S]*?<\/think>/gi, '') // Remove reasoning tokens if any
  .replace(/```json/gi, '')
  .replace(/```/gi, '')
  .trim();

let match = {};
try {
  match = JSON.parse(cleanJson);
} catch (e) {
  const m = cleanJson.match(/\{[\s\S]*\}/);
  if (m) {
    match = JSON.parse(m[0]);
  } else {
    throw new Error('Failed to parse AI completion as valid JSON.');
  }
}

// 3. Compute required skills score (60% weight)
const requiredSkills = jd.required_skills || [];
const totalRequiredWeight = requiredSkills.reduce((sum, item) => sum + item.weight, 0);

const matchedSkillsList = (match.skills_matched || []).map(s => s.toLowerCase().trim());
const earnedRequiredWeight = requiredSkills.reduce((sum, item) => {
  const itemSkill = item.skill.toLowerCase().trim();
  const isFound = matchedSkillsList.some(s => s === itemSkill || s.includes(itemSkill) || itemSkill.includes(s));
  return sum + (isFound ? item.weight : 0);
}, 0);

const skillsPct = totalRequiredWeight > 0 ? (earnedRequiredWeight / totalRequiredWeight) : 0;

// 4. Compute nice-to-have bonus (up to 10%)
const niceToHaveList = jd.nice_to_have || [];
const matchedNiceCount = (match.nice_to_have_matched || []).length;
const niceBonus = niceToHaveList.length > 0 
  ? Math.min((matchedNiceCount / niceToHaveList.length) * 0.10, 0.10) 
  : 0;

// 5. Compute experience score (30% weight)
const detectedYears = typeof match.experience_years_actual === 'number' && match.experience_years_actual > 0
  ? match.experience_years_actual
  : (Number(prev.yearsExperienceClaimed) || 0);

const minYears = jd.min_experience_years || 1;
const expPct = Math.min(detectedYears / minYears, 1.0);

// 6. Compute education score (10% weight)
const eduPct = match.education_match ? 1.0 : 0.3;

// 7. Calculate final score out of 100
let finalScore = Math.round(
  (skillsPct * 0.60) * 100 +
  (expPct * 0.30) * 100 +
  (eduPct * 0.10) * 100 +
  (niceBonus * 100)
);
finalScore = Math.max(0, Math.min(100, finalScore));

// 8. Assign decision zone & recommendation label
let zone = 'auto_reject';
let recommendation = 'WEAK_MATCH';

if (finalScore >= 80) {
  zone = 'auto_approve';
  recommendation = 'STRONG_MATCH';
} else if (finalScore >= 60) {
  zone = 'manual_review';
  recommendation = 'GOOD_MATCH';
}

// 9. Helper to serialize array attributes into clean, readable strings for Google Sheets
const formatList = (val) => {
  if (Array.isArray(val)) return val.join(' | ');
  return (val || '').toString();
};

return {
  json: {
    applicantName: prev.applicantName,
    applicantEmail: prev.applicantEmail,
    applicantPhone: prev.applicantPhone,
    appliedPosition: prev.position || prev.appliedPosition,
    extractedSkills: match.extracted_skills || [],
    skillsMatched: match.skills_matched || [],
    missingSkills: match.missing_skills || [],
    niceToHaveMatched: match.nice_to_have_matched || [],
    companies: formatList(match.companies),
    projects: formatList(match.projects),
    trainingsCertifications: formatList(match.trainings_certifications),
    experienceYearsActual: detectedYears,
    minExperienceRequired: minYears,
    educationDetected: match.education_detected || '',
    educationMatch: Boolean(match.education_match),
    finalScore,
    skillsPct: Math.round(skillsPct * 100),
    experiencePct: Math.round(expPct * 100),
    fitSummary: match.fit_summary || '',
    recommendation,
    zone,
    pipelineStage: 'Screened',
    status: finalScore >= 80 ? 'Pending Review' : 'Auto-Rejected',
    executionId: ($execution && $execution.id) ? $execution.id : 'manual_test',
    timestamp: new Date().toISOString(),
  }
};
